import hashlib

def __generateKeystream(key: str, length: int) -> bytes:
    # Generate a keystream of the specified length using the provided key. The keystream is generated by hashing the key with SHA-256 and repeating the hash until the desired length is reached.
    # Create a SHA-256 hash of the key
    stream = bytearray()
    counter = 0
    while len(stream) < length:
        block = hashlib.sha256(key + counter.to_bytes(4, 'big')).digest()
        stream.extend(block)
        counter += 1
    return bytes(stream[:length])

def xorCrypto(data: bytes, key: str) -> bytes:
    # Encrypt or decrypt data using XOR with a keystream generated from the provided key.
    if not key:
        raise ValueError("Key must not be empty.")
    keystream = __generateKeystream(key.encode(), len(data))
    return bytes(b ^ k for b, k in zip(data, keystream))